# pack_custom_textures.ps1
#
# Composites the source textures in handheld/data/images/custom/ into the
# game's shared atlases, so they can be used by the terrain renderer and the
# inventory GUI:
#
#   * terrain.png (256x256, 16x16 cells): the block textures themselves.
#     The WEB/SDL build only loads terrain.png; atlas indices are
#     row * 16 + column (see WOOD_TEXTURES in Tile.cpp).
#
#   * gui/gui_blocks.png: the flat 48x48 isometric icons used by the
#     inventory / crafting GUI (see ItemRenderer::getAtlasPos). Icons are
#     generated by coloring an existing vanilla icon with the average color
#     of the source texture, keeping its shading.
#     - planks:  re-colored from the oak planks icon (5)
#     - slabs:   re-colored from the wood slab icon (30)
#     - stairs:  re-colored from the wood stairs icon (22)
#
# Run it again whenever the PNGs in images/custom/ change:
#     powershell -ExecutionPolicy Bypass -File handheld/tools/pack_custom_textures.ps1

Add-Type -AssemblyName System.Drawing

$ErrorActionPreference = 'Stop'

$root      = Split-Path -Parent $PSScriptRoot
$imagesDir = Join-Path $root 'data\images'
$customDir = Join-Path $imagesDir 'custom'
$terrainPath = Join-Path $imagesDir 'terrain.png'
$guiPath     = Join-Path $imagesDir 'gui\gui_blocks.png'

$iconCols = 10
$iconSize = 48

# file            atlas cell (col,row)   flat GUI plank icon
#                 -> terrain index = row*16+col
$blocks = @(
    @{ file = 'spruce_planks.png'; col = 4; row = 11; iconIndex = 84; iconSource = 5 }, # 5 = oak planks icon
    @{ file = 'birch_planks.png';  col = 5; row = 11; iconIndex = 83; iconSource = 5 }
)

# Terrain cells without a GUI icon (the item is rendered as a 3D block, or is
# not obtainable at all):
#   * portal.png -> nether portal swirl (PortalTile, tile id 90)
$terrainBlocks = @(
    @{ file = 'portal.png'; col = 10; row = 6 }
)

# Icons that only exist in the GUI (the terrain cells are shared with the
# plank textures above). Index meanings:
#   85/86 = birch/spruce slab   (vanilla source: 30, the wood slab icon)
#   87/88 = birch/spruce stairs (vanilla source: 22, the wood stairs icon)
$guiOnlyIcons = @(
    @{ file = 'birch_planks.png';  iconIndex = 85; iconSource = 30 },
    @{ file = 'spruce_planks.png'; iconIndex = 86; iconSource = 30 },
    @{ file = 'birch_planks.png';  iconIndex = 87; iconSource = 22 },
    @{ file = 'spruce_planks.png'; iconIndex = 88; iconSource = 22 }
)

function Get-OpaqueAverage([System.Drawing.Bitmap]$bmp) {
    [long]$r = 0; [long]$g = 0; [long]$b = 0; [long]$n = 0
    for ($y = 0; $y -lt $bmp.Height; $y++) {
        for ($x = 0; $x -lt $bmp.Width; $x++) {
            $p = $bmp.GetPixel($x, $y)
            if ($p.A -eq 0) { continue }
            $r += $p.R; $g += $p.G; $b += $p.B; $n++
        }
    }
    if ($n -eq 0) { throw 'texture has no opaque pixels' }
    return @{ R = $r / $n; G = $g / $n; B = $b / $n }
}

function Get-IconBitmap([System.Drawing.Bitmap]$gui, [int]$iconIndex) {
    $x = ($iconIndex % $iconCols) * $iconSize
    $y = [int][Math]::Floor($iconIndex / $iconCols) * $iconSize
    $bmp = New-Object System.Drawing.Bitmap $iconSize, $iconSize
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.DrawImage($gui, (New-Object System.Drawing.Rectangle 0, 0, $iconSize, $iconSize), (New-Object System.Drawing.Rectangle $x, $y, $iconSize, $iconSize), 'Pixel')
    $g.Dispose()
    return $bmp
}

function Get-AverageLuminance([System.Drawing.Bitmap]$bmp) {
    [double]$sum = 0; [long]$n = 0
    for ($y = 0; $y -lt $bmp.Height; $y++) {
        for ($x = 0; $x -lt $bmp.Width; $x++) {
            $p = $bmp.GetPixel($x, $y)
            if ($p.A -eq 0) { continue }
            $sum += 0.299 * $p.R + 0.587 * $p.G + 0.114 * $p.B
            $n++
        }
    }
    return $sum / $n
}

# Tints the source icon with the average color of the texture (keeping the
# icon's own shading) and writes the result into the GUI atlas.
function Write-TintedIcon([System.Drawing.Bitmap]$guiNew, [System.Drawing.Bitmap]$srcIcon, [int]$iconIndex, $avg) {
    $lumAvg = Get-AverageLuminance $srcIcon
    $dstX = ($iconIndex % $iconCols) * $iconSize
    $dstY = [int][Math]::Floor($iconIndex / $iconCols) * $iconSize
    for ($y = 0; $y -lt $iconSize; $y++) {
        for ($x = 0; $x -lt $iconSize; $x++) {
            $p = $srcIcon.GetPixel($x, $y)
            if ($p.A -eq 0) {
                $guiNew.SetPixel($dstX + $x, $dstY + $y, [System.Drawing.Color]::FromArgb(0, 0, 0, 0))
                continue
            }
            $lum = 0.299 * $p.R + 0.587 * $p.G + 0.114 * $p.B
            $scale = $lum / $lumAvg
            $nr = [int][Math]::Min(255, [Math]::Max(0, $avg.R * $scale))
            $ng = [int][Math]::Min(255, [Math]::Max(0, $avg.G * $scale))
            $nb = [int][Math]::Min(255, [Math]::Max(0, $avg.B * $scale))
            $guiNew.SetPixel($dstX + $x, $dstY + $y, [System.Drawing.Color]::FromArgb($p.A, $nr, $ng, $nb))
        }
    }
}

# --- backup the current atlases -------------------------------------------------
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupDir = Join-Path $env:TEMP "opencode\atlas_backup_$stamp"
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
Copy-Item $terrainPath (Join-Path $backupDir 'terrain.png')
Copy-Item $guiPath     (Join-Path $backupDir 'gui_blocks.png')
Write-Host "Backups: $backupDir"

$terrain = [System.Drawing.Bitmap]::FromFile($terrainPath)
$gui     = [System.Drawing.Bitmap]::FromFile($guiPath)

# Work on copies (FromFile locks the file)
$terrainNew = New-Object System.Drawing.Bitmap $terrain
$guiNew     = New-Object System.Drawing.Bitmap $gui
$terrain.Dispose(); $gui.Dispose()

# 1) Planks: terrain cells + flat GUI icons ------------------------------------
foreach ($b in $blocks) {
    $filePath = Join-Path $customDir $b.file
    $tex = [System.Drawing.Bitmap]::FromFile($filePath)
    if ($tex.Width -ne 16 -or $tex.Height -ne 16) {
        throw "$($b.file): expected a 16x16 PNG, got $($tex.Width)x$($tex.Height)"
    }

    # Terrain atlas
    $dstX = $b.col * 16
    $dstY = $b.row * 16
    for ($y = 0; $y -lt 16; $y++) {
        for ($x = 0; $x -lt 16; $x++) {
            $terrainNew.SetPixel($dstX + $x, $dstY + $y, $tex.GetPixel($x, $y))
        }
    }

    # Flat GUI icon
    $avg = Get-OpaqueAverage $tex
    $srcIcon = Get-IconBitmap $guiNew $b.iconSource
    Write-TintedIcon $guiNew $srcIcon $b.iconIndex $avg
    $srcIcon.Dispose()

    $tex.Dispose()
    Write-Host ("{0}: terrain cell ({1},{2}) [idx {3}] and GUI icon {4} (from icon {5})" -f $b.file, $b.col, $b.row, ($b.row * 16 + $b.col), $b.iconIndex, $b.iconSource)
}

# 2) GUI-only icons (slabs and stairs share the plank textures) ----------------
foreach ($b in $guiOnlyIcons) {
    $filePath = Join-Path $customDir $b.file
    $tex = [System.Drawing.Bitmap]::FromFile($filePath)
    $avg = Get-OpaqueAverage $tex
    $srcIcon = Get-IconBitmap $guiNew $b.iconSource
    Write-TintedIcon $guiNew $srcIcon $b.iconIndex $avg
    $srcIcon.Dispose()
    $tex.Dispose()
    Write-Host ("{0}: GUI icon {1} (from icon {2})" -f $b.file, $b.iconIndex, $b.iconSource)
}

# 3) Terrain-only cells --------------------------------------------------------
foreach ($b in $terrainBlocks) {
    $filePath = Join-Path $customDir $b.file
    $tex = [System.Drawing.Bitmap]::FromFile($filePath)
    if ($tex.Width -ne 16 -or $tex.Height -ne 16) {
        throw "$($b.file): expected a 16x16 PNG, got $($tex.Width)x$($tex.Height)"
    }

    $dstX = $b.col * 16
    $dstY = $b.row * 16
    for ($y = 0; $y -lt 16; $y++) {
        for ($x = 0; $x -lt 16; $x++) {
            $terrainNew.SetPixel($dstX + $x, $dstY + $y, $tex.GetPixel($x, $y))
        }
    }

    $tex.Dispose()
    Write-Host ("{0}: terrain cell ({1},{2}) [idx {3}]" -f $b.file, $b.col, $b.row, ($b.row * 16 + $b.col))
}

$terrainNew.Save($terrainPath, [System.Drawing.Imaging.ImageFormat]::Png)
$guiNew.Save($guiPath, [System.Drawing.Imaging.ImageFormat]::Png)
$terrainNew.Dispose()
$guiNew.Dispose()

Write-Host 'Done.'
